export const SUITS = {
  clubs: 'clubs',
  diamonds: 'diamonds',
  hearts: 'hearts',
  spades: 'spades',
} as const;

export type Suit = (typeof SUITS)[keyof typeof SUITS];  // 'clubs' | ...

export function parseSuit(raw: string): Suit {
  if (Object.values(SUITS).includes(raw as Suit)) return raw as Suit;
  throw new Error(`unknown suit: ${raw}`);
}

